<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1120;
        --panel: rgba(15, 23, 42, 0.92);
        --panel-border: rgba(148, 163, 184, 0.2);
        --text: #e5eefb;
        --muted: #94a3b8;
        --accent: #7c3aed;
        --accent-strong: #8b5cf6;
        --input: rgba(30, 41, 59, 0.95);
        --input-border: rgba(148, 163, 184, 0.28);
        --error: #fda4af;
        --shadow: 0 24px 70px rgba(2, 6, 23, 0.55);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Arial, Helvetica, sans-serif;
        background:
          radial-gradient(circle at top, rgba(124, 58, 237, 0.28), transparent 32%),
          linear-gradient(180deg, #020617 0%, #0f172a 100%);
        color: var(--text);
        display: grid;
        place-items: center;
        padding: 32px 20px;
      }

      .support-shell {
        width: min(100%, 520px);
        background: var(--panel);
        border: 1px solid var(--panel-border);
        border-radius: 20px;
        box-shadow: var(--shadow);
        padding: 32px;
        backdrop-filter: blur(14px);
      }

      h1 {
        margin: 0 0 12px;
        font-size: 2rem;
        line-height: 1.1;
      }

      .intro {
        margin: 0 0 28px;
        color: var(--muted);
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 20px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-weight: 700;
      }

      input {
        width: 100%;
        border: 1px solid var(--input-border);
        border-radius: 12px;
        background: var(--input);
        color: var(--text);
        padding: 14px 16px;
        font: inherit;
        transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
      }

      input::placeholder {
        color: #64748b;
      }

      input:focus {
        outline: none;
        border-color: var(--accent-strong);
        box-shadow: 0 0 0 4px rgba(124, 58, 237, 0.2);
      }

      input[aria-invalid="true"] {
        border-color: #fb7185;
        box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.14);
      }

      .helper-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.92rem;
        line-height: 1.5;
      }

      .error-message {
        min-height: 1.25em;
        margin: 0;
        color: var(--error);
        font-size: 0.92rem;
      }

      button {
        border: 0;
        border-radius: 12px;
        padding: 14px 18px;
        font: inherit;
        font-weight: 700;
        color: #fff;
        background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
        cursor: pointer;
        transition: transform 0.2s ease, filter 0.2s ease;
      }

      button:hover,
      button:focus-visible {
        transform: translateY(-1px);
        filter: brightness(1.08);
        outline: none;
      }

      .status-message {
        min-height: 1.4em;
        margin: 4px 0 0;
        color: #86efac;
        font-weight: 700;
      }

      @media (max-width: 560px) {
        .support-shell {
          padding: 24px;
        }
      }
    </style>
  </head>
  <body>
    <main class="support-shell">
      <h1>Contact support</h1>
      <p class="intro">
        Send us your details and a support specialist will follow up with you shortly.
      </p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name</label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            placeholder="Jordan Lee"
            required
            aria-describedby="full-name-error"
          />
          <p class="error-message" id="full-name-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="email">Email address</label>
          <input
            id="email"
            name="email"
            type="email"
            autocomplete="email"
            placeholder="jordan@example.com"
            required
            aria-describedby="email-error"
          />
          <p class="error-message" id="email-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="phone">Phone number</label>
          <input
            id="phone"
            name="phone"
            type="tel"
            autocomplete="tel"
            placeholder="+1 555-123-4567"
            aria-describedby="phone-help phone-error"
          />
          <p class="helper-text" id="phone-help">
            Optional. Use digits, spaces, hyphens, parentheses, and an optional leading +,
            for example: +1 555-123-4567.
          </p>
          <p class="error-message" id="phone-error" aria-live="polite"></p>
        </div>

        <button type="submit">Submit request</button>
        <p class="status-message" id="form-status" aria-live="polite"></p>
      </form>
    </main>

    <script>
      const form = document.getElementById("support-form");
      const statusMessage = document.getElementById("form-status");

      const fieldConfig = {
        fullName: {
          input: document.getElementById("full-name"),
          error: document.getElementById("full-name-error"),
          validate(value) {
            if (!value.trim()) {
              return "Full name is required.";
            }
            if (value.trim().length < 2) {
              return "Enter your full name.";
            }
            return "";
          },
        },
        email: {
          input: document.getElementById("email"),
          error: document.getElementById("email-error"),
          validate(value) {
            if (!value.trim()) {
              return "Email address is required.";
            }
            const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailPattern.test(value.trim())) {
              return "Enter a valid email address.";
            }
            return "";
          },
        },
        phone: {
          input: document.getElementById("phone"),
          error: document.getElementById("phone-error"),
          validate(value) {
            const trimmedValue = value.trim();
            if (!trimmedValue) {
              return "";
            }
            const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
            if (!phonePattern.test(trimmedValue)) {
              return "Enter a valid phone number in the expected format.";
            }
            return "";
          },
        },
      };

      function setFieldError(field, message) {
        field.error.textContent = message;
        field.input.setAttribute("aria-invalid", message ? "true" : "false");
      }

      function validateField(fieldName) {
        const field = fieldConfig[fieldName];
        const message = field.validate(field.input.value);
        setFieldError(field, message);
        return !message;
      }

      Object.keys(fieldConfig).forEach((fieldName) => {
        const { input } = fieldConfig[fieldName];
        input.addEventListener("input", () => {
          validateField(fieldName);
          statusMessage.textContent = "";
        });
        input.addEventListener("blur", () => {
          validateField(fieldName);
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const isValid = Object.keys(fieldConfig).every((fieldName) => validateField(fieldName));

        if (!isValid) {
          statusMessage.textContent = "Please correct the highlighted fields.";
          return;
        }

        statusMessage.textContent = "Your support request is ready to send.";
        form.reset();
        Object.values(fieldConfig).forEach((field) => setFieldError(field, ""));
      });
    </script>
  </body>
</html>
